package GPForum::Performance::Report;
use v5.40;
use utf8;
use Exporter qw(import);
use JSON::PP;
use GPForum::Performance::Compare qw(configuration_differences);

# Reports are generated by the trusted core-only publisher.
use constant {    ## no critic (ValuesAndExpressions::ProhibitConstantPragma)
    CELL_LIMIT          => 500,
    MIB                 => 1_048_576,
    PROVENANCE_POSITION => 5,
};

our $VERSION   = '0.001';
our @EXPORT_OK = qw(report);

sub _cell ($value) {
    $value = defined $value ? "$value" : 'None';
    $value =~ s/[|]/\\|/gmsx;
    $value =~ s/[\r\n]/ /gmsx;
    $value =~ s/</&lt;/gmsx;
    return substr $value, 0, CELL_LIMIT;
}

sub _number ($value) {
    return defined $value ? sprintf '%.3f', $value : '—';
}
sub _json ($value) { return JSON::PP->new->canonical->encode($value); }

sub _changes ($comparison) {
    my @changes =
      map { sprintf '%s: %+.1f%%', $_, $comparison->{deltas_pct}{$_} }
      sort keys %{ $comparison->{deltas_pct} };
    return join q{, }, @changes;
}

sub _measurement ($row) {
    my $metrics  = $row->{metrics};
    my @settings = map { _cell( $row->{$_} // '—' ) }
      qw(generator reactor workers concurrency);
    my $settings = join q{ / }, @settings;
    my $rss      = $metrics->{rss_bytes};
    my @fields   = (
        _cell("$row->{kind}:$row->{scenario}"),
        $settings,
        $row->{repetitions},
        "$row->{status} ($row->{evidence_quality})",
        _number(
            $metrics->{requests_per_second} // $metrics->{messages_per_second}
        ),
        _number( $metrics->{p50_ms} ),
        _number( $metrics->{p95_ms} // $metrics->{sql_execution_ms} ),
        _number( $metrics->{p99_ms} ),
        _number( $metrics->{cpu_percent} ) . q{ / }
          . _number( defined $rss ? $rss / MIB : undef ),
        $row->{comparison}{classification},
    );
    return q{| } . join( q{ | }, @fields ) . q{ |};
}

sub _configurations ($summary) {
    my @lines = (
        q{},
        '## Reactor and worker configuration changes',
        q{},
'These compare configurations within this run; they are not commit regressions.',
        q{},
'| Scenario | Configuration | Compared with | Concurrency | Classification | Percentage changes |',
        q{| --- | --- | --- | ---: | --- | --- |},
    );
    for my $field (qw(reactor workers)) {
        my @rows = grep { $_->{kind} eq 'http' && exists $_->{$field} }
          @{ $summary->{measurements} };
        for my $difference ( @{ configuration_differences( \@rows, $field ) } )
        {
            push @lines,
              q{| }
              . join( q{ | },
                _cell( $difference->{scenario} ),
                "$field=" . _cell( $difference->{value} ),
                _cell( $difference->{baseline_value} ),
                $difference->{concurrency} // '—',
                $difference->{comparison}{classification},
                _cell( _changes( $difference->{comparison} ) ) ) . q{ |};
        }
    }
    return @lines;
}

sub report ( $metadata, $summary ) {
    my $runner = $metadata->{runner};
    my @lines  = (
        '# GPForum continuous performance evidence',
        q{},
"Commit: `$metadata->{commit}` · mode: **$metadata->{mode}** · status: **$summary->{status}**",
"Run: $metadata->{run_id} / attempt $metadata->{run_attempt} · $metadata->{timestamp}",
        q{},
        'Runner: '
          . _cell( $runner->{label} ) . q{, }
          . _cell( $runner->{os} ) . q{/}
          . _cell( $runner->{arch} ) . q{, }
          . _cell( $runner->{cpu_count} )
          . ' CPUs, '
          . _cell( $runner->{cpu_model} ) . q{.},
        q{},
        'Versions: ' . _cell( _json( $metadata->{versions} ) ),
        q{},
        'Dataset: ' . _cell( _json( $metadata->{dataset} ) ),
        q{},
        'Baseline: '
          . _cell( $summary->{baseline}{reason} ) . q{ }
          . ( $summary->{baseline}{commit} // q{} ),
        q{},
'Values below are medians of repetitions; SQL times remain separate from HTTP time. Timing comparisons are advisory.',
        q{},
'| Scenario | Generator / reactor / workers / concurrency | Repeats | Status | req/s or msg/s | p50 ms | p95 ms | p99 ms | CPU % / RSS MiB | Comparison |',
        q{| --- | --- | ---: | --- | ---: | ---: | ---: | ---: | --- | --- |},
    );
    if ( $metadata->{dirty} ) {
        splice @lines, PROVENANCE_POSITION, 0,
'Working tree contains tracked changes; this local run is not evidence of a clean commit. Relevant diff SHA-256: `'
          . $metadata->{working_tree_diff_sha256} . q{`.};
    }
    push @lines, map { _measurement($_) } @{ $summary->{measurements} };
    push @lines, q{}, '## Baseline changes', q{},
      '| Scenario | Classification | Percentage changes |',
      q{| --- | --- | --- |};
    for my $row ( @{ $summary->{measurements} } ) {
        if ( keys %{ $row->{comparison}{deltas_pct} } ) {
            push @lines,
              q{| }
              . join( q{ | },
                _cell( $row->{scenario} ),
                $row->{comparison}{classification},
                _cell( _changes( $row->{comparison} ) ) ) . q{ |};
        }
    }
    push @lines, _configurations($summary), q{},
      '## Suite status and skipped tests', q{};
    for my $name ( sort keys %{ $summary->{suites} } ) {
        my $state = $summary->{suites}{$name};
        push @lines,
            q{- }
          . _cell($name) . q{: **}
          . _cell( $state->{status} ) . '** — '
          . _cell( $state->{reason} // q{} );
        push @lines,
          map { q{  - } . _cell( _json($_) ) } @{ $state->{skipped} // [] };
    }
    push @lines, q{}, '## Limits', q{},
      map { q{- } . _cell($_) } @{ $summary->{limitations} };
    push @lines, q{}, "[Persistent history]($metadata->{history_url})";
    if ( $metadata->{artifact_url} ) {
        push @lines, "[Artifacts]($metadata->{artifact_url})";
    }
    if ( !$metadata->{artifact_url} && $metadata->{run_url} ) {
        push @lines, "[Run and artifacts]($metadata->{run_url})";
    }
    return join( "\n", @lines ) . "\n";
}
1;
